import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
BASE='http://localhost:8080'
def get(path, token):
    while True:
        req=urllib.request.Request(BASE+path,headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req,timeout=20) as r: return json.loads(r.read())
        except urllib.error.HTTPError as e:
            body=json.loads(e.read().decode(errors='replace'))
            if e.code==429:
                time.sleep(float(body['retry_after'])); continue
            if e.code in (401,403): raise PermissionError
            raise RuntimeError((e.code,body))
def tok():
    req=urllib.request.Request(BASE+'/token',method='POST')
    with urllib.request.urlopen(req,timeout=20) as r:return json.loads(r.read())['token']
orders=json.load(open('/tmp/spring-recon/orders.json'))
seen=set(); uniq=[]; dups=0
for o in orders:
    if o['id'] in seen: dups+=1; continue
    seen.add(o['id']); uniq.append(o)
qual=[]
start=datetime(2025,3,1,tzinfo=timezone.utc); end=datetime(2025,6,1,tzinfo=timezone.utc)
for o in uniq:
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if o['status']=='shipped' and start<=dt<end: qual.append(o)
print('qualifying orders',len(qual),'unique qualifying customers',len({o['customer_id'] for o in qual}),flush=True)
customers={}; token=tok()
for i,cid in enumerate(sorted({o['customer_id'] for o in qual}),1):
    while True:
        try: c=get('/customers/'+cid,token); break
        except PermissionError: token=tok()
    customers[cid]=c
    if i%5==0: token=tok()
    time.sleep(.35)
regions={r:0 for r in ('north','south','east','west')}
for o in qual:
    c=customers[o['customer_id']]
    # round half up: amount * (100-discount) / 100, all inputs nonnegative
    discounted=(o['amount_cents']*(100-c['discount_pct'])+50)//100
    regions[c['region']]+=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':dups,'by_region':regions}
assert sum(regions.values())==result['total_cents']
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result,indent=2))
